import java.math.BigInteger;

class Solution {
    public int[] plusOne(int[] digits) {
        StringBuilder text = new StringBuilder();
        for (int digit : digits) {
            text.append(digit);
        }
        String incremented = new BigInteger(text.toString()).add(BigInteger.ONE).toString();
        int[] result = new int[incremented.length()];
        for (int index = 0; index < incremented.length(); index++) {
            result[index] = incremented.charAt(index) - '0';
        }
        return result;
    }
}

